<script setup>
import {onMounted,ref} from 'vue'
import {apiGet,apiRequest} from '../services/api.js'
import {readApsFile,canonical} from '../utils/import-aps.js'
import {formatarDataHora} from '../utils/format.js'
import {useAuthStore} from '../stores/auth.js'
const auth=useAuthStore(),file=ref(null),source=ref(null),report=ref(null),last=ref(null),generate=ref(false),busy=ref(false),error=ref('')
async function choose(e){error.value='';report.value=null;try{file.value=e.target.files[0];source.value=await readApsFile(file.value)}catch(e){error.value=e.message;source.value=null}}
async function submit(preview){busy.value=true;error.value='';try{report.value=await apiRequest('/aps/import','POST',{...source.value,filename:file.value.name,generate:generate.value,preview});if(!preview)last.value=await apiGet('/aps/import/last')}catch(e){error.value=e.message}finally{busy.value=false}}
onMounted(async()=>{try{last.value=await apiGet('/aps/import/last');generate.value=auth.publicDemo}catch(e){error.value=e.message}})
</script>
<template><p class="eyebrow">BASE CONSOLIDADA · CARGA VALIDADA</p><h1>Importar exportação (Klingo ou SOC/S+)</h1><p>Arquivo CSV ou XLSX, primeira aba, até 1000 linhas e 5 MB. Obrigatórias: matrícula, nome, empresa e status. Nenhuma leitura automática da pasta dados-evento.</p><p v-if="auth.publicDemo" class="alert alert-info">Simulação com gravação real no banco fictício. Importe somente dados de teste. O roteiro desta visita é separado; cadastros legados continuam compartilhados.</p><p data-demo="ultima-carga">Última carga: {{last?.created_at?formatarDataHora(last.created_at):'nenhuma nesta visita'}}</p><p v-if="error" role="alert" class="alert alert-danger">{{error}}</p><label class="form-label" for="aps-file">Selecione a exportação</label><input id="aps-file" type="file" accept=".csv,.xlsx" class="form-control mb-3" @change="choose"><label v-if="auth.publicDemo" class="form-check mb-3"><input v-model="generate" type="checkbox" class="form-check-input">Gerar somente campos do cuidado vazios · dados_de_teste=true</label>
<section v-if="source" class="card card-body"><h2 class="h5">Confira o mapeamento antes de gravar</h2><div class="row g-2"><label v-for="(header,i) in source.headers" :key="i" class="col-md-4">{{header}}<select v-model="source.mapping[i]" class="form-select" @change="report=null"><option value="">Ignorar</option><option v-for="(aliases,key) in canonical" :key="key" :value="key">{{aliases[0]}}</option></select></label></div><button class="btn btn-outline-success mt-3" :disabled="busy" @click="submit(true)">Validar e mostrar prévia</button><button v-if="report?.valid && !report.imported" class="btn btn-success mt-2" :disabled="busy" @click="submit(false)">Importar {{report.valid}} linhas válidas</button></section>
<section v-if="report || last?.report" class="card card-body mt-4"><h2 class="h5">Relatório da carga</h2><template v-for="r in [report||last.report]"><p>{{r.imported}} importadas · {{r.valid}} válidas · {{r.errors.length}} erros · {{r.warnings.length}} avisos</p><p v-for="(e,i) in [...r.errors,...r.warnings]" :key="i">Linha {{e.line}}: {{e.message}}</p><div class="table-responsive"><table class="table"><thead><tr><th>Matrícula</th><th>Nome</th><th>CPF</th><th>Telefone</th><th>Status</th></tr></thead><tbody><tr v-for="p in r.preview" :key="p.registration"><td>{{p.registration}}</td><td>{{p.name}}</td><td>{{p.cpf}}</td><td>{{p.phone}}</td><td>{{p.status}}</td></tr></tbody></table></div></template></section></template>
